import { z } from "zod";
import { CloseButton } from "./ButtonWidget.mjs";
import { jsx } from "./makeWidget.mjs";
const zAlertProps = z.object({
    text: z.string(),
    dismiss: z.string().default("OK"),
});
export function Alert(define) {
    return define("Alert")
        .props(zAlertProps)
        .children((props) => [
        jsx(CloseButton, {
            id: "dismiss",
            label: props.dismiss,
            hotkey: "Enter",
            closeWith: undefined,
        }),
    ])
        .render((props) => ({ text: props.text }));
}
